import math

def check_n(n):
    for a in range(1, 100):
        for b in range(a + 1, 100):
            x = a + b
            y = a * b
            coeff_c2 = x
            coeff_c1 = x**2 + y + 1 - 4 * n * y
            coeff_c0 = x * (y + 1)
            discriminant = coeff_c1**2 - 4 * coeff_c2 * coeff_c0
            if discriminant >= 0:
                sqrt_d = int(math.isqrt(discriminant))
                if sqrt_d * sqrt_d == discriminant:
                    for sol_c in [(-coeff_c1 + sqrt_d) // (2 * coeff_c2),
                                  (-coeff_c1 - sqrt_d) // (2 * coeff_c2)]:
                        if sol_c > 0 and sol_c != a and sol_c != b:
                            if (a + b + sol_c) * (a*b + b*sol_c + sol_c*a + 1) == 4 * n * a * b * sol_c:
                                return (a, b, sol_c)
    return None

print(f"n=1: {check_n(1)}")
print(f"n=2: {check_n(2)}")
print(f"n=3: {check_n(3)}")
